import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, interpolate, spring } from '../remotionShim';
// Load Google Fonts
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map(f => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]);

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;600;700`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};



export type SoldStickerProps = Record<string, any>;

const SoldSticker: React.FC<SoldStickerProps> = ({
  backgroundColor = "#ffffff",
  transparentBackground = false,
  durationInSeconds = 5,
  stickerText = "SOLD",
  stickerColor = "#D32F2F",
  textColor = "#FFFFFF",
  checkmarkColor = "#2E7D32",
  stickerScale = 1.0,
  rotation = -12,
}) => {
  useFontLoader(["Black Ops One"]);

  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // --- Logic & Helpers ---
  const bgColor = transparentBackground ? "transparent" : backgroundColor;
  
  // Animation 1: Sticker Slam
  // Starts large (scale 3) and transparent, slams down to scale 1
  const slamFrame = frame;
  const stickerSpring = spring({
    frame: slamFrame,
    fps,
    config: {
      damping: 12, // slightly bouncy
      stiffness: 150,
      mass: 0.8,
    },
  });

  const scaleVal = interpolate(stickerSpring, [0, 1], [3, 1]);
  const opacityVal = interpolate(slamFrame, [0, 5], [0, 1], {
    extrapolateRight: "clamp",
    extrapolateLeft: "clamp",
  });

  // Animation 2: Checkmark Drawing
  // Starts after the slam settles (approx frame 15)
  const checkmarkDelay = 15;
  const checkmarkFrame = Math.max(0, frame - checkmarkDelay);
  
  const checkmarkProgress = spring({
    frame: checkmarkFrame,
    fps,
    config: {
      damping: 20,
      stiffness: 100,
    },
  });
  
  // Path length for checkmark is approx 100 units based on viewBox 0 0 100 100
  // Path: M 20 55 L 45 80 L 85 20
  // Seg 1: ~35, Seg 2: ~72 => Total ~107
  const pathLength = 110;
  const strokeDashoffset = interpolate(checkmarkProgress, [0, 1], [pathLength, 0]);

  // Checkmark pop-in scale
  const checkmarkScale = spring({
    frame: checkmarkFrame - 5, // start scaling slightly before drawing finishes for better feel
    fps,
    config: { damping: 15, stiffness: 120 },
  });

  return (
    <AbsoluteFill
      style={{
        backgroundColor: bgColor,
        justifyContent: "center",
        alignItems: "center",
        fontFamily: "'Black Ops One', cursive",
      }}
    >
      {/* Container for centering both elements */}
      <div
        style={{
          display: "flex",
          flexDirection: "column",
          alignItems: "center",
          justifyContent: "center",
          gap: 20,
          transform: `scale(${stickerScale})`,
        }}
      >
        {/* STICKER */}
        <div
          style={{
            backgroundColor: stickerColor,
            color: textColor,
            padding: "20px 60px",
            border: `8px solid ${textColor}`,
            borderRadius: "12px",
            fontSize: "clamp(60px, 10vw, 120px)",
            lineHeight: 1,
            boxShadow: "0 10px 30px rgba(0,0,0,0.3)",
            transform: `rotate(${rotation}deg) scale(${scaleVal})`,
            opacity: opacityVal,
            textAlign: "center",
            // "Grunge" border effect using double borders
            outline: `4px dashed ${stickerColor}`,
            outlineOffset: "-14px",
          }}
        >
          {stickerText.toUpperCase()}
        </div>

        {/* CHECKMARK */}
        <div
          style={{
            marginTop: 20,
            transform: `scale(${checkmarkScale})`,
            opacity: checkmarkFrame > 0 ? 1 : 0,
          }}
        >
          <svg
            width="120"
            height="120"
            viewBox="0 0 100 100"
            fill="none"
            xmlns="http://www.w3.org/2000/svg"
            style={{
                filter: "drop-shadow(0px 4px 6px rgba(0,0,0,0.2))"
            }}
          >
            <path
              d="M 20 55 L 45 80 L 85 20"
              stroke={checkmarkColor}
              strokeWidth="12"
              strokeLinecap="round"
              strokeLinejoin="round"
              strokeDasharray={pathLength}
              strokeDashoffset={strokeDashoffset}
            />
          </svg>
        </div>
      </div>
    </AbsoluteFill>
  );
};

export default SoldSticker;